'use client';

import { useState, useEffect } from "react";
import forge from "node-forge";

export default function HomePage() {
  const [publicKey, setPublicKey] = useState<string | null>(null);
  const [secret, setSecret] = useState<string>("My top secret message!");
  const [decryptedMessage, setDecryptedMessage] = useState<string>("");
  const [status, setStatus] = useState<string>("Ready");

  // 1. Fetch the public key from our API
  useEffect(() => {
    const fetchKey = async () => {
      setStatus("Fetching public key...");
      const response = await fetch("/api/key");
      const data = await response.json();
      if (data.publicKey) {
        setPublicKey(data.publicKey);
        setStatus("Public key loaded. Ready to encrypt.");
      } else {
        setStatus("Error loading public key.");
      }
    };
    fetchKey();
  }, []);

  // 2. Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!publicKey) {
      alert("Public key is not available.");
      return;
    }
    setStatus("Encrypting...");

    // 3. Encrypt the data using the public key with node-forge
    const rsa = forge.pki.publicKeyFromAsn1(
      forge.util.decode64(publicKey)
    );
    const encrypted = rsa.encrypt(secret, "RSA-OAEP", {
        md: forge.md.sha256.create(),
    });

    // 4. Send the encrypted data (as Base64) to the backend
    setStatus("Sending encrypted data to server...");
    const response = await fetch("/api/process", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ encryptedData: forge.util.encode64(encrypted) }),
    });

    const result = await response.json();

    if (result.success) {
      setStatus("Success! ✅");
      setDecryptedMessage(result.message); // Display the decrypted message from the server
    } else {
      setStatus(`Error: ${result.error}`);
    }
  };

  return (
    <main className="p-8 font-sans">
      <h1>AWS KMS Asymmetric Encryption Demo</h1>
      <p><b>Status:</b> {status}</p>
      
      <form onSubmit={handleSubmit}>
        <label htmlFor="secret" className="block my-2">
          Secret to Encrypt:
        </label>
        <input
          id="secret"
          type="text"
          value={secret}
          onChange={(e) => setSecret(e.target.value)}
          className="w-80 p-2"
        />
        <button type="submit" disabled={!publicKey} className="p-2 ml-2">
          Encrypt and Decrypt
        </button>
      </form>

      {decryptedMessage && (
        <div className="mt-6 p-4 bg-green-100 border border-green-500">
          <h3>🔓 Server Response (Decrypted Message):</h3>
          <p><b>{decryptedMessage}</b></p>
        </div>
      )}
    </main>
  );
}